const temporaryDirectory = fs.mkdtempSync(path.join(os.tmpdir(), "wled-rgb-calibration-"));
const executable = path.join(temporaryDirectory, process.platform === "win32" ? "rgb_calibration_checks.exe" : "rgb_calibration_checks");

function run(command, argumentsList) {
	const result = childProcess.spawnSync(command, argumentsList, { encoding: "utf8", shell: false });
	if (result.error) throw new Error(`${command} could not start: ${result.error.message}`);
	if (result.status !== 0) {
		const output = [result.stdout, result.stderr].filter(Boolean).join("\n");
		throw new Error(`${command} failed with exit code ${result.status}${output ? `:\n${output}` : ""}`);
	}
	if (result.stdout) process.stdout.write(result.stdout);
	if (result.stderr) process.stderr.write(result.stderr);
}
